void application_PI_hk1_trigger( void ){
    //Increase the time field by 1
    //Reset the default each time just as test for now


    //Spacecraft Time ICD
    tm_3_25_1.second = tm_3_25_1.second + 1;
    if(tm_3_25_1.second == 60){
        tm_3_25_1.second = 0;
        tm_3_25_1.minute = tm_3_25_1.minute + 1;
        if(tm_3_25_1.minute == 60){
            tm_3_25_1.minute = 0;
            tm_3_25_1.hour = tm_3_25_1.hour + 1;
            if(tm_3_25_1.hour == 24){
                tm_3_25_1.hour = 0;
                tm_3_25_1.day = tm_3_25_1.day + 1;
            }
        }
    }

    // Need to convert the tm_3_25 struct into a byte array

    //asn1SccByte_Array PusData = {0};
    int Counter = 0;

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.sid >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.sid);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.fsw_db_ver >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.fsw_db_ver);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.day >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.day);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.hour >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.hour);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.minute >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.minute);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.second >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.second);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.sc_id >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.sc_id);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.cmd_rcv_count >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.cmd_rcv_count);

    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.cmd_acc_cnt >> 8);
    pusPacket.pus_data.arr[Counter++] = (uint8_t)(tm_3_25_1.cmd_acc_cnt);

    //PusData.nCount = Counter;
    // pusPacket.pus_data.nCount = Counter;
    pusPacket.pus_data_count = Counter;

    //Now create the header
    buildPUSHeader(&pusPacket, 2, 1, 3, 25, 1, 0, pusPacket.pus_pfield.arr[0] ,pusPacket.pus_time.arr);

    //Now build pus should have all the info needed
    application_RI_build_pus_packet( &pusPacket, &pusPacketBytes );

    uint8_t test_value = pusPacketBytes.nCount + 2 - 1;

    // buildSPHeader(&spacePacket, 0, 0, 1, 100, 3, 1, 0);
    buildSPHeader(&spacePacket, 0, 0, 1, 100, 3, 1, pusPacketBytes.nCount + 2 - 1);
    spacePacket.packet_data_length = 29;

    application_RI_build_space_packet( &spacePacket , &pusPacketBytes, &spacePacketBytes);

}

